class FalseList:
 def __bool__(self):
  print("truth")
  return False
print(__import__("pkg.child",fromlist=FalseList()).__name__)

def names():
 yield "child"
 raise ValueError("names")
try: __import__("pkg",fromlist=names())
except ValueError as e: print(str(e))
print(__import__("pkg").child.x)

class Spec:
 @property
 def parent(self):
  print("parent")
  return "pkg"
print(__import__("child",{"__spec__":Spec()},None,["x"],1).x)

class Spec:
 @property
 def parent(self):
  print("parent")
  return "pkg"
print(__import__("child",{"__package__":"pkg","__spec__":Spec()},None,["x"],1).x)

def wrong(*args): raise ValueError("wrong")
__import__=wrong
import helper
print(helper.x)
try: __import__("helper")
except ValueError: print("explicit shadow")

class Result:
 x=7
def custom(name,g,l,fromlist,level):
 print(name,g is ns,l is local,*fromlist,level)
 return Result
ns={"__builtins__":{"__import__":custom}}
local={}
exec("from chosen import x",ns,local)
print(local["x"])

def custom(name,g,l,fromlist,level):
 print(name,g is ns,l is None,fromlist is None,level)
 return 9
ns={"__builtins__":{"__import__":custom}}
exec("def f(x):\n import chosen\n return chosen",ns)
print(ns["f"](7))

def custom(*args):
 print("captured")
 return 7
ns={"__builtins__":{"__import__":custom}}
exec("def f():\n import chosen\n return chosen",ns)
ns["__builtins__"]={}
print(ns["f"]())

def custom(*args):
 print("callback")
 raise ValueError("failed")
try: exec("import chosen",{"__builtins__":{"__import__":custom}})
except ValueError as e: print(str(e))

import state
for i in [7,9]:
 try: __import__("bad")
 except ValueError as e: print(str(e),len(state.calls))

